public boolean validateRebateTable()
{
    TAMRebateTable  rebateTableLoc,rebateTableCount;
    TAMRebateDeal   rebateDeal;
    boolean rateSet=false,value=false;
    int rateCount=0,valueCount=0;

    boolean ret;

    select firstonly rebateDeal
        where rebateDeal.RecId == this.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select count(RecId) from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal;

        if (rebateTableLoc.RecId > 2)
        {
            throw error("@MET:METVolumetricValidation");
        }

        select firstonly METTierLineType, RecId from rebateTableLoc
            where rebateTableLoc.RebateDeal == this.RebateDeal
            && rebateTableLoc.RecId != this.RecId;

        if (rebateTableLoc.RecId && this.RecId != rebateTableLoc.RecId && rebateTableLoc.METTierLineType == this.METTierLineType)
        {
            throw error("Volumetric rebate cannot have similar tier line type");
        }

        //if (rebateTableLoc.RecId == 2)
        //{
        //    while select rebateTableCount
        //        where rebateTableCount.RebateDeal == this.RebateDeal
        //    {
        //        if (rebateTableCount.METTierLineType == METTierLineType::Rate)
        //        {
        //            rateSet = true;
        //            rateCount++;
        //        }
        //        if (rebateTableCount.METTierLineType == METTierLineType::Value)
        //        {
        //            value = true;
        //            valueCount++;
        //        }
        //    }
        //    if (rateSet == false || rateCount != 1 || value == false || valueCount != 1)
        //    {
        //        throw error("Volumetric rebate cannot have similar tier line type");
        //    }
        //}
    }
    return ret;
}

